            Item::Use(_) => *self.term_counts.entry("use".to_string()).or_insert(0) += 1,
            Item::Type(_) => *self.term_counts.entry("type".to_string()).or_insert(0) += 1,
            Item::Const(_) => *self.term_counts.entry("const".to_string()).or_insert(0) += 1,
